import React, { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { Menu, X, ChevronDown } from 'lucide-react'

const Navigation = ({ currentPage = 'home', setCurrentPage }) => {
  const [isOpen, setIsOpen] = useState(false)
  const [scrolled, setScrolled] = useState(false)
  const [activeSection, setActiveSection] = useState('hero')

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20)
    }

    const handleSectionChange = () => {
      const sections = ['hero', 'about', 'events', 'members', 'gallery', 'contact']
      const current = sections.find(section => {
        const element = document.getElementById(section)
        if (element) {
          const rect = element.getBoundingClientRect()
          return rect.top <= 100 && rect.bottom >= 100
        }
        return false
      })
      if (current) setActiveSection(current)
    }

    window.addEventListener('scroll', handleScroll)
    window.addEventListener('scroll', handleSectionChange)
    return () => {
      window.removeEventListener('scroll', handleScroll)
      window.removeEventListener('scroll', handleSectionChange)
    }
  }, [])

  const scrollToSection = (sectionId) => {
    if (currentPage !== 'home') {
      setCurrentPage('home')
      setTimeout(() => {
        const element = document.getElementById(sectionId)
        if (element) {
          element.scrollIntoView({ behavior: 'smooth' })
        }
      }, 100)
    } else {
      const element = document.getElementById(sectionId)
      if (element) {
        element.scrollIntoView({ behavior: 'smooth' })
      }
    }
    setIsOpen(false)
  }

  const handlePageNavigation = (page) => {
    setCurrentPage(page)
    setIsOpen(false)
  }

  const navLinks = [
    { id: 'hero', label: 'Home', type: 'section' },
    { id: 'about', label: 'About', type: 'section' },
    { id: 'events', label: 'Events', type: 'section' },
    { id: 'members', label: 'Members', type: 'section' },
    { id: 'gallery', label: 'Gallery', type: 'section' },
    { id: 'contact', label: 'Contact', type: 'section' },
    { id: 'blog', label: 'Blog', type: 'page' }
  ]

  return (
    <motion.header
      initial={{ y: -100 }}
      animate={{ y: 0 }}
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        scrolled 
          ? 'bg-dark/95 backdrop-blur-md shadow-lg' 
          : 'bg-dark/60 backdrop-blur-sm'
      }`}
    >
      <div className="container mx-auto px-4">
        <div className="flex items-center justify-between h-20">
          {/* Logo */}
          <motion.div
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.2 }}
            className="flex-shrink-0"
          >
            <button
              onClick={() => scrollToSection('hero')}
              className="text-white font-heading text-xl md:text-2xl font-bold hover:text-accent transition-colors"
            >
              HighSchoolive Africa
            </button>
          </motion.div>

          {/* Desktop Navigation */}
          <nav className="hidden lg:flex items-center space-x-8">
            {navLinks.map((link, index) => (
              <motion.button
                key={link.id}
                initial={{ opacity: 0, y: -10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.1 * index }}
                onClick={() => 
                  link.type === 'page' 
                    ? handlePageNavigation(link.id)
                    : scrollToSection(link.id)
                }
                className={`relative text-sm font-medium transition-colors hover:text-accent ${
                  (link.type === 'page' && currentPage === link.id) ||
                  (link.type === 'section' && activeSection === link.id && currentPage === 'home')
                    ? 'text-accent'
                    : 'text-white'
                }`}
              >
                {link.label}
                {((link.type === 'page' && currentPage === link.id) ||
                  (link.type === 'section' && activeSection === link.id && currentPage === 'home')) && (
                  <motion.div
                    layoutId="activeIndicator"
                    className="absolute -bottom-1 left-0 right-0 h-0.5 bg-accent"
                  />
                )}
              </motion.button>
            ))}
          </nav>

          {/* CTA Button */}
          <motion.button
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.3 }}
            onClick={() => scrollToSection('events')}
            className="hidden lg:block bg-accent hover:bg-accent/90 text-dark font-semibold px-6 py-2 rounded-full transition-all duration-300 hover:scale-105"
          >
            Book Event
          </motion.button>

          {/* Mobile Menu Toggle */}
          <button
            onClick={() => setIsOpen(!isOpen)}
            className="lg:hidden text-white p-2 rounded-md hover:bg-white/10 transition-colors"
            aria-label="Toggle menu"
          >
            {isOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>
      </div>

      {/* Mobile Menu */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className="lg:hidden bg-dark/95 backdrop-blur-md border-t border-white/10"
          >
            <div className="container mx-auto px-4 py-6">
              <nav className="flex flex-col space-y-4">
                {navLinks.map((link, index) => (
                  <motion.button
                    key={link.id}
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{ delay: 0.1 * index }}
                    onClick={() => 
                      link.type === 'page' 
                        ? handlePageNavigation(link.id)
                        : scrollToSection(link.id)
                    }
                    className={`text-left py-2 px-4 rounded-md transition-colors ${
                      (link.type === 'page' && currentPage === link.id) ||
                      (link.type === 'section' && activeSection === link.id && currentPage === 'home')
                        ? 'text-accent bg-accent/10' 
                        : 'text-white hover:text-accent hover:bg-white/5'
                    }`}
                  >
                    {link.label}
                  </motion.button>
                ))}
                <motion.button
                  initial={{ opacity: 0, x: -20 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: 0.6 }}
                  onClick={() => scrollToSection('events')}
                  className="mt-4 bg-accent hover:bg-accent/90 text-dark font-semibold py-3 px-6 rounded-full transition-all duration-300"
                >
                  Book Event
                </motion.button>
              </nav>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.header>
  )
}

export default Navigation

